const crypto = require('crypto');

const EVENTS = ['item:added', 'item:updated', 'item:completed', 'item:deleted'];
const ignored = (why) => [{ json: { status: 200, reply: `ignored: ${why}` } }];

// Todoist signs the raw request body, so verify before parsing anything.
const raw = await this.helpers.getBinaryDataBuffer(0, 'data');
const given = Buffer.from($input.first().json.headers['x-todoist-hmac-sha256'] ?? '');
const secret = $env.TODOIST_CLIENT_SECRET;
if (!secret) throw new Error('TODOIST_CLIENT_SECRET is not set');
const expected = Buffer.from(crypto.createHmac('sha256', secret).update(raw).digest('base64'));
if (given.length !== expected.length || !crypto.timingSafeEqual(given, expected)) {
  return [{ json: { status: 401, reply: 'bad signature' } }];
}

const { event_name, event_data: item, event_data_extra: extra } = JSON.parse(raw.toString('utf8'));
if (!EVENTS.includes(event_name)) return ignored(event_name);

// Todoist API priority is inverted: 4 = p1, 1 = p4
const prio = (p) => `p${5 - (p ?? 1)}`;
const due = (d) => d?.string || d?.date || 'none';
const labels = (l) => (l?.length ? l.join(', ') : 'none');
const clip = (s, n = 300) => (s.length > n ? `${s.slice(0, n - 1)}…` : s);
// Older webhook payloads carry numeric ids plus v2_* ids; the API wants the latter.
const projectId = (i) => i?.v2_project_id ?? i?.project_id;

const changes = [];
if (event_name === 'item:updated') {
  // Completing, uncompleting, and every occurrence of a recurring task also
  // send item:updated; those have their own events.
  const intent = extra?.update_intent;
  if (intent && intent !== 'item_updated') return ignored(`update_intent ${intent}`);

  const old = extra?.old_item;
  if (old) {
    const diff = (name, a, b) => { if (a !== b) changes.push({ name, value: clip(`${a} → ${b}`), inline: false }); };
    diff('Content', old.content, item.content);
    diff('Due', due(old.due), due(item.due));
    diff('Priority', prio(old.priority), prio(item.priority));
    diff('Labels', labels(old.labels), labels(item.labels));
    if ((old.description ?? '') !== (item.description ?? '')) changes.push({ name: 'Description', value: 'changed', inline: false });
    if (projectId(old) !== projectId(item)) changes.push({ name: 'Moved', value: 'from another project', inline: false });
    // Names are resolved later, where the collaborators are looked up.
    if ((old.responsible_uid ?? null) !== (item.responsible_uid ?? null)) changes.push({ name: 'Assigned to', from: old.responsible_uid ?? null, to: item.responsible_uid ?? null, inline: false });
    // Reordering, collapsing, and similar edits are not worth a message.
    if (!changes.length) return ignored('no visible change');
  }
}

// Only shared projects have assignees, so most events skip the collaborator lookup.
const needs_people = Boolean(item.responsible_uid) || changes.some((c) => c.name === 'Assigned to');
return [{ json: { status: 200, event_name, item, changes, project_id: projectId(item) ?? '', needs_people } }];

const ICON = { 'item:added': '➕', 'item:updated': '✏️', 'item:completed': '✅', 'item:deleted': '🗑️' };

const { event_name, item, changes, project_id } = $('Verify and parse').first().json;

// Walk from the task's project up through its parents. Empty when the lookup
// failed, for instance before the Todoist credential is connected.
const byId = new Map(($('Get projects').first().json.results ?? []).map((p) => [p.id, p]));
const chain = [];
for (let p = byId.get(project_id); p && chain.length < 10; p = byId.get(p.parent_id)) chain.push(p);
const project = chain.map((p) => p.name).reverse().join(' / ');

// {"Project name": "https://discord.com/api/webhooks/..."}; the nearest mapped
// project wins, so sub-projects inherit. Everything else goes to the default.
let channels = {};
try {
  const parsed = JSON.parse($env.DISCORD_PROJECT_WEBHOOKS || '{}');
  for (const [name, url] of Object.entries(parsed)) channels[name.trim().toLowerCase()] = url;
} catch (e) {
  channels = {};
}
const mapped = chain.find((p) => channels[p.name.trim().toLowerCase()]);
const webhook_url = mapped ? channels[mapped.name.trim().toLowerCase()] : $env.DISCORD_WEBHOOK_URL;

// Assignee names come from the project's collaborators, fetched only when the
// event involves an assignee.
const assigneeChange = changes.find((c) => c.name === 'Assigned to');
const people = new Map();
if ($('Get collaborators').isExecuted) {
  for (const c of $('Get collaborators').first().json.results ?? []) people.set(String(c.id), c.name);
}
const person = (uid) => (uid ? people.get(String(uid)) ?? 'someone' : 'nobody');

// One line per event: icon, task, then only the details that exist.
const task_id = String(item.v2_id ?? item.id);
const name = (item.content ?? '').replace(/\s+/g, ' ').trim().slice(0, 300);
// Angle brackets stop Discord unfurling the link. A name with brackets of its
// own would break the markdown, and finished tasks have nothing to open.
const linked = ['item:added', 'item:updated'].includes(event_name) && !/[\[\]]/.test(name);
const parts = [`${ICON[event_name]} ${linked ? `[${name}](<https://app.todoist.com/app/task/${task_id}>)` : name}`];

if (event_name === 'item:updated') {
  for (const c of changes) parts.push(c === assigneeChange ? `${c.name}: ${person(c.from)} → ${person(c.to)}` : `${c.name}: ${c.value}`);
} else if (event_name === 'item:added') {
  if (item.due?.string) parts.push(item.due.string);
  // Todoist API priority is inverted: 4 = p1, 1 = p4
  if (item.priority > 1) parts.push(`p${5 - item.priority}`);
  if (item.responsible_uid) parts.push(person(item.responsible_uid));
}
// In a project's own channel the project is redundant; in the default channel
// it is the only thing that says where the task lives.
if (project && !mapped) parts.push(`in ${project}`);

return [{
  json: {
    event_name,
    task_id,
    name,
    webhook_url,
    // Task text goes into message content now, where an @everyone would ping.
    discord: { content: parts.join(' · ').slice(0, 1900), allowed_mentions: { parse: [] }, flags: 4 },
  },
}];

// With a bot token the message is posted by the application itself, which is
// the only way a message can carry a working button. Without one, or if the
// bot cannot post in the channel, the webhook node after this one delivers it.
const crypto = require('crypto');

const { event_name, task_id, name, webhook_url, discord } = $input.first().json;
const viaWebhook = (why) => [{ json: { delivered: false, why, webhook_url, discord } }];

const token = $env.DISCORD_BOT_TOKEN;
if (!token) return viaWebhook('no bot token');

const api = async (method, path, body) => {
  for (let attempt = 0; ; attempt++) {
    try {
      return await this.helpers.httpRequest({
        method, url: `https://discord.com/api/v10${path}`, body, json: true, timeout: 8000,
        headers: { Authorization: `Bot ${token}` },
      });
    } catch (e) {
      // A burst of events hits Discord's rate limit. The error reaches a Code
      // node as little more than its text, so match on that and wait a fixed,
      // growing interval rather than the retry_after Discord sent.
      const limited = [e.httpCode, e.response?.status, e.status].some((c) => Number(c) === 429) || /\b429\b/.test(String(e.message));
      if (limited && attempt < 3) {
        await new Promise((r) => setTimeout(r, 1500 * (attempt + 1)));
        continue;
      }
      throw e;
    }
  }
};

try {
  // Which channel the webhook posts to, remembered for a day and keyed by a
  // hash because the URL itself is a credential.
  const cache = $getWorkflowStaticData('global');
  cache.channels ??= {};
  const key = crypto.createHash('sha256').update(webhook_url).digest('hex');
  let hit = cache.channels[key];
  if (!hit || Date.now() - hit.at > 86400000) {
    hit = { id: (await this.helpers.httpRequest({ url: webhook_url, json: true, timeout: 8000 })).channel_id, at: Date.now() };
    cache.channels[key] = hit;
  }
  const channel = hit.id;

  if (event_name === 'item:completed' || event_name === 'item:deleted') {
    // Find the task's "added" message by its Done button and retire it. No
    // store is needed: the button's custom_id carries the task id, and a
    // retired message keeps the button, disabled.
    const recent = await api('GET', `/channels/${channel}/messages?limit=100`);
    const button = (m) => (m.components ?? []).flatMap((row) => row.components ?? []).find((c) => c.custom_id === `done:${task_id}`);
    const original = recent.find(button);
    if (original) {
      // Already retired means someone pressed the button, and the message
      // changing under their finger was the announcement. Say nothing more.
      if (button(original).disabled) return [{ json: { delivered: true, channel, note: 'completed with the button; no second message' } }];
      const icon = event_name === 'item:completed' ? '✅' : '🗑️';
      await api('PATCH', `/channels/${channel}/messages/${original.id}`, {
        content: `${icon} ~~${name}~~`,
        components: [{ type: 1, components: [{ type: 2, style: 2, label: event_name === 'item:completed' ? 'Done' : 'Deleted', custom_id: `done:${task_id}`, disabled: true }] }],
        allowed_mentions: { parse: [] },
      });
    }
  }

  const message = { ...discord };
  if (event_name === 'item:added') {
    message.components = [{ type: 1, components: [{ type: 2, style: 3, label: 'Done', custom_id: `done:${task_id}` }] }];
  }
  await api('POST', `/channels/${channel}/messages`, message);
  return [{ json: { delivered: true, channel } }];
} catch (e) {
  return viaWebhook(`bot delivery failed: ${e.message}`);
}
